import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-03-25","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-03-25","date":"2026-03-25T00:00:00.000Z","updated":"2026-05-14T00:00:00.000Z","tags":["RGW","rate limiting","Teuthology","lifecycle policy","object storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-25.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-25.md","lastUpdated":1780460162000}'),o={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-25.md"};function r(n,e,c,s,u,h){return i(),t("div",null,[...e[0]||(e[0]=[l('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph RGW Refactoring Meeting 于 2026 年 3 月 25 日召开，主要讨论了三个议题：RGW list 请求的 CPU 时间限速方案、Teuthology 测试套件的修复策略，以及 copy object 压缩加密 bug 修复与 lifecycle transition 重构计划。</p><h2 id="议题一-rgw-list-请求限速——基于时间的-rate-limiting" tabindex="-1">议题一：RGW List 请求限速——基于时间的 rate limiting <a class="header-anchor" href="#议题一-rgw-list-请求限速——基于时间的-rate-limiting" aria-label="Permalink to &quot;议题一：RGW List 请求限速——基于时间的 rate limiting&quot;">​</a></h2><h3 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h3><p>David 和 Sanjay 介绍了一个新的 PR，旨在为 RGW 的 list 请求引入基于 CPU 时间的 rate limiting 机制。</p><p>当前 RGW 已有针对 ops 数量和读写字节数（bandwidth）的限速，但对于 list 请求，这些指标不足以防止单个用户对集群造成冲击。核心原因在于：</p><ul><li>当 list 请求携带 delimiter 参数时，RocksDB（OMap）需要执行大量 range scan，每次找到 delimiter 边界变化都需要发起一次新的数据库查询。</li><li>由于 Ceph 的 bucket sharding 机制，跨 shard 的查询更加复杂，无法预知需要跳过多少条目。</li><li>一个客户端请求可能导致数 MB/s 的 RocksDB IO，远超 ops/s 指标所能描述的范围。</li></ul><h3 id="方案讨论" tabindex="-1">方案讨论 <a class="header-anchor" href="#方案讨论" aria-label="Permalink to &quot;方案讨论&quot;">​</a></h3><p>与会者讨论了多种限速指标的优劣：</p><ul><li><strong>时间（time）</strong>：最能反映请求对系统资源的实际消耗，包括 IO 等待和处理时间，但对用户而言不够直观，且受服务器负载影响。</li><li><strong>RocksDB / OMap IOPS</strong>：更贴近底层开销，但对用户完全不透明，难以解释限速原因。</li><li><strong>ops 数量</strong>：已有实现，但无法区分轻量与重量级 list 请求。</li></ul><p>最终倾向于采用时间作为度量指标，理由是：</p><ol><li>用户可以感知请求耗时，具备一定可解释性。</li><li>时间是对系统资源占用最综合的估算，未来 listing 性能优化（如 sharding 改进）也会自然反映在时间指标上，具备 future-proof 特性。</li><li>实现方式与现有 bandwidth 限速类似，预算在操作完成后扣除，保证至少一次 list 操作始终可执行。</li></ol><p>注意：应将该指标定义为&quot;时间&quot;而非&quot;CPU 时间&quot;，因为大量耗时实际发生在后端 IO（如 OMAP busy），不会体现在 RGW 进程的 CPU 使用率上。</p><h3 id="版本兼容性关注" tabindex="-1">版本兼容性关注 <a class="header-anchor" href="#版本兼容性关注" aria-label="Permalink to &quot;版本兼容性关注&quot;">​</a></h3><p>David 特别指出，该 PR 修改了存储限速配置的 JSON 结构版本号。若上游 main 分支同期有其他字段变更，将产生版本冲突，因此希望尽快明确该 PR 能否合入 main。</p><h3 id="结论与后续行动" tabindex="-1">结论与后续行动 <a class="header-anchor" href="#结论与后续行动" aria-label="Permalink to &quot;结论与后续行动&quot;">​</a></h3><ul><li>与会者达成基本共识，认为基于时间的 list 请求限速方案合理可行。</li><li>将请求 Mark Kogan（rate limiting 主要贡献者）对该 PR 进行 review。</li><li>David 将在 PR 中补充本次讨论的结论摘要。</li></ul><h2 id="议题二-teuthology-rgw-测试套件修复" tabindex="-1">议题二：Teuthology RGW 测试套件修复 <a class="header-anchor" href="#议题二-teuthology-rgw-测试套件修复" aria-label="Permalink to &quot;议题二：Teuthology RGW 测试套件修复&quot;">​</a></h2><h3 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h3><p>RGW 测试套件（Teuthology）近期因 Rakuten 相关支持代码合入，出现大量测试失败，严重影响 PR 的 merge 验证流程。</p><p>主要失败来源：</p><ul><li><strong>ragweed</strong>：依赖 boto2，已过时。Mark 有一个待合入的 PR 尝试通过 AI 生成兼容层来修复，但引入了不必要的抽象层，需要进一步评估。</li><li><strong>Rocky 10 相关</strong>：Redis 安装失败、cloud events 模块导入失败等问题，部分为 Rocky 特定问题。</li><li><strong>upgrade 测试</strong>：因Squid 和 Tentacle 缺少 Rocky 包，upgrade 测试套件整体失败。</li></ul><h3 id="讨论与决策" tabindex="-1">讨论与决策 <a class="header-anchor" href="#讨论与决策" aria-label="Permalink to &quot;讨论与决策&quot;">​</a></h3><ul><li><strong>ragweed 处理方案</strong>：优先测试 Mark 的 PR，若可用则合入；若不可用，则将 ragweed 从 <code>rgw verify</code>（基础测试套件）中移除，保留在 upgrade 套件中，避免阻塞日常 PR 验证。</li><li><strong>ragweed 的价值评估</strong>：与会者认为 ragweed 目前主要用于 upgrade 测试（如跨版本 multipart upload），但多年未新增测试用例，实际价值有限。</li><li><strong>其他失败</strong>：Oguzhan 将在 Slack 发布 Teuthology 运行分析摘要，并为各类失败创建 tracker issue，优先级标记为 urgent。</li><li>后续计划新增对最新 Ubuntu LTS 的测试支持，届时 Python 兼容性问题预计已基本解决。</li></ul><h3 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>将 ragweed 从 <code>rgw verify</code> 测试套件中移除（由本次会议参与者作为 action item跟进）。</li><li>为各类 Teuthology 失败创建 tracker issue，标记为 urgent 优先级。</li><li>在 Slack 发布 Teuthology 运行分析摘要。</li></ul><h2 id="议题三-copy-object-压缩加密-bug-修复与-lifecycle-transition-重构" tabindex="-1">议题三：Copy Object 压缩加密 Bug 修复与 Lifecycle Transition 重构 <a class="header-anchor" href="#议题三-copy-object-压缩加密-bug-修复与-lifecycle-transition-重构" aria-label="Permalink to &quot;议题三：Copy Object 压缩加密 Bug 修复与 Lifecycle Transition 重构&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>Matt 介绍了 PR #6725，该 PR 旨在为 lifecycle policy 的 transition 操作添加 recompression 和 re-encryption 支持（用于将对象迁移至新 storage pool）。</p><p>在编写 DPF（Data Processing Framework）过程中，发现 transition 与 copy object 存在大量重复逻辑，因此提议抽取公共基类，供两者共用。</p><p>同时，在测试中发现 copy object 对压缩和加密对象存在 bug（tracker issue #75650）：对压缩加密对象执行 copy object 会返回损坏数据。该 bug 在 main 分支于去年 11 月合入，尚未 backport 到 Tentacle。</p><h3 id="方案讨论-1" tabindex="-1">方案讨论 <a class="header-anchor" href="#方案讨论-1" aria-label="Permalink to &quot;方案讨论&quot;">​</a></h3><ul><li>与会者认同抽取共享 DPF 基类的方向，可减少代码重复，降低 bug 风险。</li><li>共享 DPF 未来还可用于 deduplication 场景（内存中解压缩并计算 fingerprint）。</li><li>建议优先单独提交一个 PR 修复 copy object 的压缩加密 bug，使 Teuthology 测试尽快恢复绿色，再推进 lifecycle 重构的泛化工作。</li></ul><h3 id="版本影响评估" tabindex="-1">版本影响评估 <a class="header-anchor" href="#版本影响评估" aria-label="Permalink to &quot;版本影响评估&quot;">​</a></h3><ul><li>该 bug仅存在于 main 分支，Tentacle 尚未受影响。</li><li>需确保在 Tentacle 预发布前完成修复，相关 backport tracker issue 已分配给 Marcus，尚未完成。</li><li>将新发现的 copy object bug 关联到现有 backport tracker，避免遗漏。</li></ul><h3 id="后续行动-1" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动-1" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>Matt 单独提交 PR 修复 copy object 压缩加密 bug。</li><li>在 PR 上tag Gabby（对共享 DPF 感兴趣）。</li><li>将新 copy object bug 关联到现有 backport tracker issue。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议在三个议题上均取得明确进展：list 请求时间限速方案获得共识并进入 review流程；Teuthology 测试套件有了清晰的修复路径；copy object 压缩加密 bug 将优先独立修复，lifecycle 重构工作同步推进。</p>',39)])])}const p=a(o,[["render",r]]);export{d as __pageData,p as default};
